"""Build the French-first V4 pages and their reviewed four-language copy."""
from pathlib import Path
import json,re,html
root=Path(__file__).resolve().parents[1]
catalog=json.loads((root/'i18n/static.json').read_text())
def T(fr,en,pt,es):
 catalog[fr]={'en':en,'pt-BR':pt,'es':es};return html.escape(fr)
def P(*a):return '<p>'+T(*a)+'</p>'
def H(*a,level=2):return f'<h{level}>'+T(*a)+f'</h{level}>'
def A(url,*a,cls='cta-button'):return f'<a class="{cls}" href="{html.escape(url,quote=True)}">'+T(*a)+'</a>'
def section(body,id=''):return f'<section'+(f' id="{id}"' if id else '')+'>'+body+'</section>'
def card(body):return '<article class="card">'+body+'</article>'
nav=[('index','Accueil','Home','Início','Inicio'),('solutions','Vos besoins','Your needs','Suas necessidades','Sus necesidades'),('approche','Comment nous travaillons','How we work','Como trabalhamos','Cómo trabajamos'),('realisations','Exemples concrets','Practical examples','Exemplos práticos','Ejemplos prácticos'),('diagnostic','Faire le point','Review your situation','Avalie sua situação','Revise su situación'),('contact','Contact','Contact','Contato','Contacto')]
brand=T('CLN Performance','CLN Performance','CLN Performance','CLN Performance')
footer=T('CLN Performance vous aide à simplifier le travail et à fiabiliser vos informations.','CLN Performance helps simplify work and make your information reliable.','A CLN Performance ajuda a simplificar o trabalho e tornar suas informações confiáveis.','CLN Performance ayuda a simplificar el trabajo y mejorar la fiabilidad de su información.')
contact_label=('Parlons de votre situation','Let’s discuss your situation','Vamos conversar sobre sua situação','Hablemos de su situación')
examples_label=('Voir des exemples concrets','See practical examples','Ver exemplos práticos','Ver ejemplos prácticos')
commercial=P('Notre objectif est un bénéfice durable et votre autonomie. Nous ne cherchons pas à installer une facturation récurrente. Selon votre projet, nous pouvons convenir d’une rémunération liée aux bénéfices effectivement constatés, avec des critères définis ensemble avant l’intervention.','Our aim is a lasting benefit and your autonomy. We do not seek to establish recurring billing. Depending on your project, we can agree on remuneration linked to benefits actually observed, with criteria defined together before work begins.','Nosso objetivo é um benefício duradouro e sua autonomia. Não buscamos estabelecer cobranças recorrentes. Conforme o projeto, podemos acordar uma remuneração ligada aos benefícios efetivamente constatados, com critérios definidos em conjunto antes da intervenção.','Nuestro objetivo es un beneficio duradero y su autonomía. No buscamos establecer una facturación recurrente. Según el proyecto, podemos acordar una remuneración vinculada a los beneficios efectivamente constatados, con criterios definidos juntos antes de intervenir.')
def page(name,title,desc,body,scripts=()):
 fulltitle=html.unescape(title)+' — CLN Performance'
 if html.unescape(title) in catalog:catalog[fulltitle]={lang:value+' — CLN Performance' for lang,value in catalog[html.unescape(title)].items()}
 head=(root/f'{name}.html').read_text()
 # Keep the legal/contact backend contract; pages generated here are editorial.
 head=re.sub(r'<title>.*?</title>','<title>'+title+' — CLN Performance</title>',head,flags=re.S)
 head=re.sub(r'<meta name="description" content="[^"]*"\s*/?>','<meta name="description" content="'+desc+'" />',head)
 header='<header><div class="navbar"><a class="brand" href="index.html"><img src="LOGO_CLN.png" alt="Logo CLN" width="42" height="42"/><span>'+brand+'</span></a><nav class="nav-links" aria-label="'+T('Navigation principale','Main navigation','Navegação principal','Navegación principal')+'">'
 for n,*labels in nav:header+=A(n+'.html',*labels,cls='active' if n==name else '')
 header+='</nav>'+A('contact.html',*contact_label)+'</div></header>'
 foot='<footer><div class="footer-inner"><p>'+footer+'</p><div class="footer-links"><a href="mailto:contact@cln-performance.com">contact@cln-performance.com</a>'+A('contact.html',*contact_label,cls='')+A('mentions-legales.html','Mentions légales','Legal notice','Aviso legal','Aviso legal',cls='')+A('confidentialite.html','Confidentialité','Privacy','Privacidade','Privacidad',cls='')+'</div></div></footer>'
 head=re.sub(r'<header>.*?</header>',header,head,flags=re.S)
 head=re.sub(r'<main>.*?</main>','<main id="main-content">'+body+'</main>',head,flags=re.S)
 head=re.sub(r'<footer>.*?</footer>',foot,head,flags=re.S)
 head=re.sub(r'<script defer src="(?:diagnostic|contact)\.js[^\"]*"></script>\s*','',head)
 for script in scripts:head=head.replace('</head>',f'<script defer src="{script}.js?v=20261029-v4"></script>\n</head>')
 head=re.sub(r'\?v=20261028-v[23]','?v=20261029-v4',head)
 if 'class="skip-link"' not in head:head=head.replace('<body>','<body>'+A('#main-content','Aller au contenu','Skip to content','Ir para o conteúdo','Ir al contenido',cls='skip-link'))
 (root/f'{name}.html').write_text(re.sub(r'>\s*<','>\n<',head))
 return header,foot
needs=[
('ressaisies',('Éviter les ressaisies','Avoid re-entering information','Evitar a redigitação','Evitar volver a introducir datos'),('Vous recopiez les mêmes informations dans plusieurs fichiers ou logiciels. CLN étudie leur circulation pour limiter les recopies, les oublis et les écarts.','You copy the same information into several files or applications. CLN examines how it flows to reduce copying, omissions and inconsistencies.','Você copia as mesmas informações em vários arquivos ou sistemas. A CLN analisa sua circulação para reduzir redigitações, esquecimentos e divergências.','Copia la misma información en varios archivos o programas. CLN estudia su circulación para reducir copias, olvidos y discrepancias.'),('Exemple : saisir une information une fois et la transmettre aux outils concernés.','Example: enter information once and pass it to the relevant tools.','Exemplo: inserir uma informação uma vez e transmiti-la às ferramentas envolvidas.','Ejemplo: introducir una información una vez y transmitirla a las herramientas pertinentes.')),
('repetitif',('Réduire les tâches répétitives','Reduce repetitive tasks','Reduzir tarefas repetitivas','Reducir tareas repetitivas'),('Vous assemblez des fichiers et envoyez les mêmes relances chaque semaine. CLN automatise les opérations adaptées ; vos équipes gardent la main sur les exceptions.','You assemble files and send the same reminders every week. CLN automates suitable operations; your teams retain control of exceptions.','Você reúne arquivos e envia os mesmos lembretes toda semana. A CLN automatiza as operações adequadas; suas equipes mantêm o controle das exceções.','Reúne archivos y envía los mismos recordatorios cada semana. CLN automatiza las operaciones adecuadas; sus equipos mantienen el control de las excepciones.'),('Bénéfice attendu : du temps pour traiter les situations qui demandent une décision.','Expected benefit: time to handle situations that need a decision.','Benefício esperado: tempo para tratar situações que exigem uma decisão.','Beneficio esperado: tiempo para atender las situaciones que requieren una decisión.')),
('chiffres',('Disposer de chiffres fiables','Work with reliable figures','Dispor de números confiáveis','Disponer de cifras fiables'),('Deux services annoncent des chiffres différents pour la même activité. CLN clarifie les sources, les définitions et les contrôles pour disposer d’informations cohérentes.','Two departments report different figures for the same activity. CLN clarifies sources, definitions and checks to provide consistent information.','Dois setores apresentam números diferentes para a mesma atividade. A CLN esclarece fontes, definições e controles para obter informações coerentes.','Dos departamentos presentan cifras distintas para la misma actividad. CLN aclara fuentes, definiciones y controles para disponer de información coherente.'),('Bénéfice attendu : comprendre les indicateurs et décider sur une base partagée.','Expected benefit: understand indicators and make decisions on a shared basis.','Benefício esperado: entender os indicadores e decidir com uma base compartilhada.','Beneficio esperado: comprender los indicadores y decidir sobre una base compartida.')),
('suivi',('Savoir où en sont les dossiers','Know the status of your cases','Saber como estão os processos','Conocer el estado de los expedientes'),('Le suivi dépend des emails ou de la mémoire d’une personne. CLN organise un suivi partagé des étapes et des échéances pour repérer les blocages plus tôt.','Tracking relies on emails or one person’s memory. CLN organises shared tracking of stages and deadlines to spot bottlenecks sooner.','O acompanhamento depende de emails ou da memória de uma pessoa. A CLN organiza o acompanhamento compartilhado de etapas e prazos para identificar bloqueios mais cedo.','El seguimiento depende de los correos o de la memoria de una persona. CLN organiza un seguimiento compartido de etapas y plazos para detectar bloqueos antes.'),('Bénéfice attendu : moins d’oublis et une continuité du travail plus facile.','Expected benefit: fewer omissions and easier continuity of work.','Benefício esperado: menos esquecimentos e mais facilidade na continuidade do trabalho.','Beneficio esperado: menos olvidos y mayor facilidad para dar continuidad al trabajo.'))]
# Home
body=section('<div><p class="hero-tagline">'+T('Simplifier votre quotidien','Simplify your daily work','Simplificar seu dia a dia','Simplificar su día a día')+'</p>'+H('Moins de tâches répétitives. Des informations fiables. Du temps pour votre activité.','Fewer repetitive tasks. Reliable information. More time for your work.','Menos tarefas repetitivas. Informações confiáveis. Mais tempo para sua atividade.','Menos tareas repetitivas. Información fiable. Más tiempo para su actividad.',level=1)+P('CLN Performance aide votre organisation à éviter les ressaisies, automatiser les tâches répétitives et mieux suivre son activité. Nous partons du travail réel de vos équipes pour améliorer vos outils et leur utilisation.','CLN Performance helps your organisation avoid re-entry, automate repetitive tasks and monitor activity. We start with your teams’ actual work to improve your tools and how they are used.','A CLN Performance ajuda sua organização a evitar redigitações, automatizar tarefas repetitivas e acompanhar melhor suas atividades. Partimos do trabalho real das equipes para melhorar suas ferramentas e sua utilização.','CLN Performance ayuda a su organización a evitar la doble introducción de datos, automatizar tareas repetitivas y seguir mejor su actividad. Partimos del trabajo real de sus equipos para mejorar sus herramientas y su uso.')+'<div class="actions">'+A('realisations.html',*examples_label)+A('contact.html',*contact_label,cls='text-link')+'</div></div><div class="before-after">'+H('Un exemple simple','A simple example','Um exemplo simples','Un ejemplo sencillo')+P('Avant : chaque semaine, une personne rassemble plusieurs fichiers pour préparer le suivi.','Before: each week, someone gathers several files to prepare a report.','Antes: toda semana, uma pessoa reúne vários arquivos para preparar o acompanhamento.','Antes: cada semana, una persona reúne varios archivos para preparar el seguimiento.')+P('Après : les fichiers sont regroupés et contrôlés automatiquement. L’équipe vérifie les anomalies et analyse les résultats.','After: files are combined and checked automatically. The team reviews exceptions and analyses results.','Depois: os arquivos são reunidos e verificados automaticamente. A equipe examina as anomalias e analisa os resultados.','Después: los archivos se agrupan y revisan automáticamente. El equipo comprueba las anomalías y analiza los resultados.')+P('Scénario illustratif, sans gain chiffré garanti.','Illustrative scenario, with no guaranteed numerical gain.','Cenário ilustrativo, sem ganho numérico garantido.','Escenario ilustrativo, sin ganancia numérica garantizada.')+'</div>').replace('<section>','<section class="hero">',1)
body+=section(H('Vous reconnaissez une de ces situations ?','Do any of these situations sound familiar?','Você reconhece alguma destas situações?','¿Reconoce alguna de estas situaciones?')+'<div class="card-grid">'+''.join(card(H(*title,level=3)+P(*desc)+A('solutions.html#'+key,'Voir ce que CLN peut changer','See what CLN can change','Veja o que a CLN pode mudar','Vea qué puede cambiar CLN',cls='text-link')) for key,title,desc,_ in needs)+'</div>')
body+=section(H('Une amélioration utile que vous pouvez garder en main','A useful improvement you can keep control of','Uma melhoria útil que você pode manter sob controle','Una mejora útil que puede mantener bajo su control')+commercial+A('approche.html#remuneration','Comprendre notre démarche','Understand our approach','Entenda nossa abordagem','Comprenda nuestro enfoque',cls='text-link'))
body+=section(H('Votre interlocuteur','Your contact','Seu interlocutor','Su interlocutor')+P('Patrick est votre interlocuteur pour comprendre votre situation et construire une amélioration avec les personnes concernées.','Patrick is your contact to understand your situation and develop an improvement with the people involved.','Patrick é seu interlocutor para entender sua situação e construir uma melhoria com as pessoas envolvidas.','Patrick es su interlocutor para comprender su situación y construir una mejora con las personas implicadas.')+A('approche.html','Découvrir les étapes de notre intervention','Discover the steps of our work','Conheça as etapas da intervenção','Conozca las etapas de nuestra intervención',cls='text-link'))
body+=section(H('Vous ne savez pas par quoi commencer ?','Not sure where to start?','Não sabe por onde começar?','¿No sabe por dónde empezar?')+A('diagnostic.html','Faire le point sur ma situation','Review my situation','Avaliar minha situação','Revisar mi situación'))
header,foot=page('index',T('Simplifier le travail et fiabiliser vos informations','Simplify work and make information reliable','Simplificar o trabalho e tornar as informações confiáveis','Simplificar el trabajo y mejorar la fiabilidad de la información'),T('Gagnez en clarté sur les tâches répétitives, les ressaisies et le suivi de votre activité avec CLN Performance.','Get clarity on repetitive tasks, re-entry and activity tracking with CLN Performance.','Tenha mais clareza sobre tarefas repetitivas, redigitações e acompanhamento com a CLN Performance.','Obtenga claridad sobre tareas repetitivas, datos duplicados y seguimiento con CLN Performance.'),body)
# Needs
body=section(H('Qu’aimeriez-vous améliorer dans votre travail ?','What would you like to improve in your work?','O que gostaria de melhorar no seu trabalho?','¿Qué le gustaría mejorar en su trabajo?',level=1)+P('Partez de votre difficulté. Nous vous aidons à définir une amélioration adaptée, avec les équipes concernées.','Start with your difficulty. We help define a suitable improvement with the teams involved.','Parta de sua dificuldade. Ajudamos a definir uma melhoria adequada com as equipes envolvidas.','Parta de su dificultad. Le ayudamos a definir una mejora adecuada con los equipos implicados.'))
for key,title,desc,gain in needs:
 body+=section(H(*title)+P(*desc)+P(*gain)+'<details><summary>'+T('Comment cela fonctionne','How it works','Como funciona','Cómo funciona')+'</summary>'+P('Nous examinons les outils, les règles de travail et les contraintes avant de proposer une solution. Selon le besoin : connexion entre logiciels, traitement automatisé de fichiers, contrôles de données ou tableau de suivi. Les accès et les essais sont définis avec vos interlocuteurs techniques.','We examine tools, working rules and constraints before proposing a solution. Depending on the need: connecting applications, processing files automatically, checking data or a tracking dashboard. Access and testing are defined with your technical contacts.','Examinamos ferramentas, regras de trabalho e restrições antes de propor uma solução. Conforme a necessidade: conexão entre sistemas, tratamento automático de arquivos, verificações de dados ou painel de acompanhamento. Acessos e testes são definidos com seus interlocutores técnicos.','Examinamos herramientas, reglas de trabajo y limitaciones antes de proponer una solución. Según la necesidad: conexión entre programas, tratamiento automático de archivos, controles de datos o cuadro de seguimiento. Los accesos y pruebas se definen con sus interlocutores técnicos.')+'</details>'+A('contact.html?need='+key,'Parlons de cette difficulté','Let’s discuss this difficulty','Vamos conversar sobre essa dificuldade','Hablemos de esta dificultad'),key)
body+=section(P('Les bénéfices sont des objectifs à évaluer selon votre contexte, pas des résultats garantis.','Benefits are objectives to assess in your context, not guaranteed results.','Os benefícios são objetivos a avaliar conforme seu contexto, não resultados garantidos.','Los beneficios son objetivos que se evalúan según su contexto, no resultados garantizados.')+A('contact.html','Mon besoin est différent','My need is different','Minha necessidade é diferente','Mi necesidad es diferente',cls='text-link'))
page('solutions',T('Vos besoins','Your needs','Suas necessidades','Sus necesidades'),T('Ressaisies, tâches répétitives, chiffres divergents ou manque de suivi : trouvez votre situation.','Re-entry, repetitive tasks, inconsistent figures or tracking issues: find your situation.','Redigitações, tarefas repetitivas, números divergentes ou falta de acompanhamento: encontre sua situação.','Datos duplicados, tareas repetitivas, cifras distintas o falta de seguimiento: encuentre su situación.'),body)
# Approach
steps=[
('Comprendre votre fonctionnement','Understand how you work','Entender seu funcionamento','Comprender su funcionamiento', 'Nous échangeons avec les équipes et examinons quelques exemples de travail. Vous obtenez une synthèse de la difficulté et de ses conséquences.','We talk with teams and examine examples of their work. You receive a summary of the difficulty and its consequences.','Conversamos com as equipes e examinamos exemplos de trabalho. Você recebe uma síntese da dificuldade e de suas consequências.','Hablamos con los equipos y examinamos ejemplos de trabajo. Obtiene una síntesis de la dificultad y de sus consecuencias.'),
('Choisir une amélioration prioritaire','Choose a priority improvement','Escolher uma melhoria prioritária','Elegir una mejora prioritaria','Nous comparons les pistes, les efforts et les bénéfices attendus. Vous validez le périmètre, le plan d’action et les critères de réussite avant la réalisation.','We compare options, effort and expected benefits. You approve the scope, action plan and success criteria before implementation.','Comparamos opções, esforços e benefícios esperados. Você valida o escopo, o plano de ação e os critérios de sucesso antes da realização.','Comparamos opciones, esfuerzos y beneficios esperados. Valida el alcance, el plan de acción y los criterios de éxito antes de la realización.'),
('Tester avec vos équipes','Test with your teams','Testar com suas equipes','Probar con sus equipos','Nous réalisons et testons sur un périmètre défini. Vos équipes vérifient le résultat ; les anomalies et les conditions de mise en service sont traitées ensemble.','We implement and test within an agreed scope. Your teams check the result; issues and launch conditions are addressed together.','Realizamos e testamos em um escopo definido. Suas equipes verificam o resultado; as anomalias e as condições de entrada em serviço são tratadas em conjunto.','Realizamos y probamos en un alcance definido. Sus equipos verifican el resultado; las anomalías y las condiciones de puesta en servicio se tratan juntos.'),
('Transmettre et mesurer les bénéfices','Hand over and measure benefits','Transmitir e medir os benefícios','Transmitir y medir los beneficios','Nous accompagnons la prise en main et remettons une documentation adaptée. Nous comparons les résultats à la situation de départ sur une période convenue, pour préparer votre autonomie.','We support adoption and provide suitable documentation. We compare results with the starting situation over an agreed period to prepare your autonomy.','Acompanhamos a utilização e entregamos documentação adequada. Comparamos os resultados com a situação inicial em um período acordado, para preparar sua autonomia.','Acompañamos la puesta en práctica y entregamos documentación adaptada. Comparamos los resultados con la situación inicial durante un período acordado, para preparar su autonomía.')]
body=section(H('Une intervention construite avec vos équipes','Work designed with your teams','Uma intervenção construída com suas equipes','Una intervención construida con sus equipos',level=1)+P('Vous connaissez votre activité. Nous apportons une méthode et les compétences nécessaires pour rendre une amélioration concrète et utilisable.','You know your activity. We bring a method and the skills needed to make an improvement practical and usable.','Você conhece sua atividade. Trazemos um método e as competências necessárias para tornar uma melhoria concreta e utilizável.','Usted conoce su actividad. Aportamos un método y las competencias necesarias para lograr una mejora concreta y utilizable.'))
body+=section('<ol class="steps">'+''.join('<li>'+H(*s[:4],level=2)+P(*s[4:])+'</li>' for s in steps)+'</ol>')
body+=section(H('Une rémunération qui peut être liée à vos bénéfices','Remuneration that can be linked to your benefits','Uma remuneração que pode estar ligada aos seus benefícios','Una remuneración que puede vincularse a sus beneficios')+commercial+P('Nous convenons des indicateurs, de la situation de départ, de la période de mesure et de la manière de constater les résultats. Les modalités de calcul et de paiement sont définies dans l’accord commercial, y compris si les résultats sont inférieurs aux attentes.','We agree on indicators, the starting situation, the measurement period and how results will be verified. Calculation and payment terms are defined in the commercial agreement, including if results fall short of expectations.','Acordamos indicadores, situação inicial, período de medição e forma de constatar os resultados. As regras de cálculo e pagamento são definidas no acordo comercial, inclusive se os resultados ficarem abaixo do esperado.','Acordamos indicadores, situación inicial, período de medición y forma de constatar los resultados. Las condiciones de cálculo y pago se definen en el acuerdo comercial, incluso si los resultados quedan por debajo de lo esperado.')+P('Du temps libéré n’est pas automatiquement une économie financière. Les coûts éventuels de logiciels ou d’hébergement sont identifiés séparément. Un besoin de suivi ultérieur fait l’objet d’un accord distinct.','Time freed up is not automatically a financial saving. Any software or hosting costs are identified separately. Any subsequent support needs are covered by a separate agreement.','Tempo liberado não é automaticamente uma economia financeira. Eventuais custos de software ou hospedagem são identificados separadamente. Necessidades posteriores de acompanhamento são objeto de um acordo distinto.','El tiempo liberado no es automáticamente un ahorro financiero. Los posibles costes de programas o alojamiento se identifican por separado. Cualquier necesidad posterior de seguimiento es objeto de un acuerdo distinto.'),'remuneration')
faq=[(('Faut-il remplacer nos outils ?','Must we replace our tools?','Precisamos substituir nossas ferramentas?','¿Hay que sustituir nuestras herramientas?'),('Nous étudions d’abord vos outils et leurs possibilités. Les changements nécessaires sont discutés avant toute réalisation.','We first examine your tools and their capabilities. Necessary changes are discussed before implementation.','Primeiro examinamos suas ferramentas e possibilidades. As mudanças necessárias são discutidas antes de qualquer realização.','Primero estudiamos sus herramientas y posibilidades. Los cambios necesarios se discuten antes de la realización.')),(('Qui doit participer ?','Who needs to take part?','Quem deve participar?','¿Quién debe participar?'),('Les personnes qui réalisent le travail, un responsable du périmètre et, selon les sujets, les interlocuteurs informatiques. Leur disponibilité est organisée au cadrage.','The people doing the work, a scope owner and, where relevant, technical contacts. Availability is planned when defining the scope.','As pessoas que realizam o trabalho, um responsável pelo escopo e, conforme o assunto, os interlocutores de informática. A disponibilidade é organizada no planejamento.','Las personas que realizan el trabajo, un responsable del alcance y, según el tema, los interlocutores informáticos. La disponibilidad se organiza al definir el alcance.')),(('Combien coûte une intervention ?','How much does an engagement cost?','Quanto custa uma intervenção?','¿Cuánto cuesta una intervención?'),('Le coût et la durée dépendent du périmètre. Nous pouvons étudier une rémunération liée aux bénéfices constatés. Il ne s’agit ni d’une gratuité annoncée, ni d’une garantie de gains.','Cost and duration depend on scope. We can discuss remuneration linked to observed benefits. This is neither an offer of free work nor a guarantee of gains.','O custo e a duração dependem do escopo. Podemos estudar uma remuneração ligada aos benefícios constatados. Não é uma oferta de gratuidade nem uma garantia de ganhos.','El coste y la duración dependen del alcance. Podemos estudiar una remuneración vinculada a los beneficios constatados. No se trata de una oferta gratuita ni de una garantía de ganancias.'))]
body+=section(H('Vos questions pratiques','Practical questions','Perguntas práticas','Preguntas prácticas')+''.join('<details><summary>'+T(*q)+'</summary>'+P(*a)+'</details>' for q,a in faq)+A('contact.html',*contact_label))
page('approche',T('Comment nous travaillons','How we work','Como trabalhamos','Cómo trabajamos'),T('Comprendre, choisir, tester, transmettre et mesurer les bénéfices avec vos équipes.','Understand, choose, test, hand over and measure benefits with your teams.','Entender, escolher, testar, transmitir e medir os benefícios com suas equipes.','Comprender, elegir, probar, transmitir y medir los beneficios con sus equipos.'),body)
