 body+=section('<p class="eyebrow">'+T('Scénario illustratif','Illustrative scenario','Cenário ilustrativo','Escenario ilustrativo')+'</p>'+H(*title)+P(*before)+P(*action)+P(*after)+A('contact.html?need='+key,'Nous rencontrons une situation similaire','We face a similar situation','Enfrentamos uma situação semelhante','Tenemos una situación similar'),key)
