page('realisations',T('Exemples concrets','Practical examples','Exemplos práticos','Ejemplos prácticos'),T('Trois scénarios avant et après pour comprendre les améliorations possibles et leur mesure.','Three before-and-after scenarios to understand potential improvements and how to measure them.','Três cenários de antes e depois para entender as melhorias possíveis e sua medição.','Tres escenarios de antes y después para comprender las mejoras posibles y su medición.'),body)
# Questionnaire codes are independent of display languages.
fields={}
def choices(name,rows,multi=False,required=False):
 fields[name]={}
 out='<div class="radio-list">'
 for i,(value,labels) in enumerate(rows):
  fields[name][value]=labels
  out+='<label><input type="'+('checkbox' if multi else 'radio')+'" name="'+name+'" value="'+value+'"'+(' required' if required and i==0 else '')+'/> '+T(*labels)+'</label>'
 return out+'</div>'
